package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.HashSet;
import java.util.Iterator;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.InfoSetUtil;
import org.apache.commons.jxpath.ri.axes.InitialContext;
import org.apache.commons.jxpath.ri.axes.SelfContext;
import org.apache.commons.jxpath.ri.context.EvalContext;
import org.apache.commons.jxpath.ri.context.InitialContext;
import org.apache.commons.jxpath.ri.context.SelfContext;
import org.apache.commons.jxpath.ri.expression.Expression;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CoreOperationCompare_equal_TriageGen0Test {

    private CoreOperationCompare compare;
    private EvalContext mockContext;
    private Expression mockLeft;
    private Expression mockRight;

    // Subclass to expose protected method for testing
    private static class TestableCoreOperationCompare extends CoreOperationCompare {
        public TestableCoreOperationCompare() {
            super(null, null);
        }

        @Override
        public boolean equal(EvalContext context, Expression left, Expression right) {
            return super.equal(context, left, right);
        }

        // Mocking the internal calls to avoid deep dependency issues
        // In a real scenario, we might use Spy or real implementations
        @Override
        protected boolean contains(Iterator it, Object value) {
            return false; // Simplified for coverage
        }

        @Override
        protected boolean findMatch(Iterator lit, Iterator rit) {
            return false; // Simplified for coverage
        }

        @Override
        protected boolean equal(Object l, Object r) {
            return Objects.equals(l, r);
        }
    }

    // Helper to mock the context behavior
    private static class MockEvalContext extends EvalContext {
        private final Object pointer;
        public MockEvalContext(Object pointer) { this.pointer = pointer; }
        @Override public Object getSingleNodePointer() { return pointer; }
    }

    @Before
    public void setUp() {
        compare = spy(new TestableCoreOperationCompare());
        mockContext = mock(EvalContext.class);
        mockLeft = mock(Expression.class);
        mockRight = mock(Expression.class);
    }

    @Test
    public void testEqual_SimpleObjects() {
        when(mockLeft.compute(mockContext)).thenReturn("A");
        when(mockRight.compute(mockContext)).thenReturn("A");
        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_SimpleObjects_NotEqual() {
        when(mockLeft.compute(mockContext)).thenReturn("A");
        when(mockRight.compute(mockContext)).thenReturn("B");
        assertFalse(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_LeftIsContext() {
        InitialContext ctx = mock(InitialContext.class);
        Object pointer = "pointer";
        when(ctx.getSingleNodePointer()).thenReturn(pointer);

        when(mockLeft.compute(mockContext)).thenReturn(ctx);
        when(mockRight.compute(mockContext)).thenReturn("A");

        // We expect it to call equal(pointer, "A")
        // Using a spy to verify the final call logic
        doReturn(true).when(compare).equal(pointer, "A");

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_RightIsSelfContext() {
        SelfContext ctx = mock(SelfContext.class);
        Object pointer = "pointer";
        when(ctx.getSingleNodePointer()).thenReturn(pointer);

        when(mockLeft.compute(mockContext)).thenReturn("A");
        when(mockRight.compute(mockContext)).thenReturn(ctx);

        doReturn(true).when(compare).equal("A", pointer);

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_LeftIsCollection() {
        List<String> list = Arrays.asList("A");
        when(mockLeft.compute(mockContext)).thenReturn(list);
        when(mockRight.compute(mockContext)).thenReturn("A");

        // l becomes Iterator, r is Object -> calls contains(Iterator, Object)
        doReturn(true).when(compare).contains(any(Iterator.class), eq("A"));

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_RightIsCollection() {
        List<String> list = Arrays.asList("A");
        when(mockLeft.compute(mockContext)).thenReturn("A");
        when(mockRight.compute(mockContext)).thenReturn(list);

        // l is Object, r becomes Iterator -> calls contains(Iterator, Object)
        doReturn(true).when(compare).contains(any(Iterator.class), eq("A"));

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_BothAreCollections() {
        List<String> list1 = Arrays.asList("A");
        List<String> list2 = Arrays.asList("A");
        when(mockLeft.compute(mockContext)).thenReturn(list1);
        when(mockRight.compute(mockContext)).thenReturn(list2);

        // Both become Iterators -> calls findMatch(Iterator, Iterator)
        doReturn(true).when(compare).findMatch(any(Iterator.class), any(Iterator.class));

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_BothAreIterators() {
        Iterator<String> it1 = Collections.singletonList("A").iterator();
        Iterator<String> it2 = Collections.singletonList("A").iterator();
        when(mockLeft.compute(mockContext)).thenReturn(it1);
        when(mockRight.compute(mockContext)).thenReturn(it2);

        doReturn(true).when(compare).findMatch(it1, it2);

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_NullValues() {
        when(mockLeft.compute(mockContext)).thenReturn(null);
        when(mockRight.compute(mockContext)).thenReturn(null);

        // Calls equal(null, null)
        doReturn(true).when(compare).equal(null, null);
        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }
}
